DROP TABLE IF EXISTS orders;
DROP VIEW IF EXISTS customer_orders;
CREATE TABLE orders (order_id INTEGER PRIMARY KEY, customer_id INTEGER, amount INTEGER);
INSERT INTO orders VALUES (1,7,500),(2,8,300),(3,7,900);
CREATE VIEW customer_orders AS SELECT order_id,customer_id,amount FROM orders;
SELECT order_id,amount FROM customer_orders WHERE customer_id=7 ORDER BY order_id;

DROP TABLE IF EXISTS wallets;
CREATE TABLE wallets (wallet_id INTEGER PRIMARY KEY, balance INTEGER);
INSERT INTO wallets VALUES (1,1000),(2,500);
BEGIN;
UPDATE wallets SET balance=balance-200 WHERE wallet_id=1;
UPDATE wallets SET balance=balance+200 WHERE wallet_id=2;
COMMIT;
SELECT wallet_id,balance FROM wallets ORDER BY wallet_id;

DROP TABLE IF EXISTS products;
DROP TABLE IF EXISTS price_audit;
CREATE TABLE products (product_id INTEGER PRIMARY KEY, price INTEGER);
CREATE TABLE price_audit (product_id INTEGER, old_price INTEGER, new_price INTEGER);
INSERT INTO products VALUES (1,100);
CREATE TRIGGER log_price_change AFTER UPDATE OF price ON products BEGIN INSERT INTO price_audit VALUES (OLD.product_id,OLD.price,NEW.price);
END;
UPDATE products SET price=125 WHERE product_id=1;
SELECT product_id,old_price,new_price FROM price_audit;

DROP TABLE IF EXISTS orders;
CREATE TABLE orders (order_id INTEGER PRIMARY KEY, customer_id INTEGER, amount INTEGER);
INSERT INTO orders VALUES (1,7,500),(2,8,300),(3,7,900);
CREATE TEMP TABLE customer_totals AS SELECT customer_id,SUM(amount) AS total_amount FROM orders GROUP BY customer_id;
SELECT customer_id,total_amount FROM customer_totals ORDER BY customer_id;

DROP TABLE IF EXISTS payments;
DROP VIEW IF EXISTS payment_totals;
CREATE TABLE payments (payment_id INTEGER PRIMARY KEY, region TEXT, amount INTEGER);
INSERT INTO payments VALUES (1,'East',200),(2,'East',300),(3,'West',400);
CREATE VIEW payment_totals AS SELECT region,SUM(amount) AS total_amount FROM payments GROUP BY region;
SELECT region,total_amount FROM payment_totals WHERE total_amount>=400 ORDER BY region;

